inline Point3<T> Point3<T>::cross(const Point3<T>& otherVector) const
{
	return Point3<T>(yCoord * otherVector.zCoord - zCoord * otherVector.yCoord,
                 zCoord * otherVector.xCoord - xCoord * otherVector.zCoord,
